"""A tiny Hungry Hippos simulator."""

from __future__ import annotations

from dataclasses import dataclass, field
from random import Random


@dataclass(frozen=True, slots=True)
class Hippo:
    name: str
    hunger: int = 0
    score: int = 0


@dataclass(frozen=True, slots=True)
class TurnResult:
    turn: int
    eater: str
    ball: str
    hunger_before: int
    hunger_after: int
    score: int


@dataclass(slots=True)
class Simulator:
    hippos: list[Hippo] = field(default_factory=list)
    balls: list[str] = field(default_factory=list)
    rng: Random = field(default_factory=Random)

    def __post_init__(self) -> None:
        if not self.hippos:
            self.hippos = [Hippo(name) for name in ("Harry", "Henry", "Hannah", "Harriet")]
        if not self.balls:
            self.balls = [f"ball-{i}" for i in range(1, 21)]

    def play_turn(self, turn: int) -> TurnResult | None:
        if not self.balls:
            return None
        idx = self.rng.randrange(len(self.hippos))
        ball_idx = self.rng.randrange(len(self.balls))
        hippo = self.hippos[idx]
        ball = self.balls.pop(ball_idx)
        updated = Hippo(name=hippo.name, hunger=hippo.hunger + 1, score=hippo.score + 1)
        self.hippos[idx] = updated
        return TurnResult(
            turn=turn,
            eater=updated.name,
            ball=ball,
            hunger_before=hippo.hunger,
            hunger_after=updated.hunger,
            score=updated.score,
        )

    def play(self, turns: int = 10) -> list[TurnResult]:
        results: list[TurnResult] = []
        for turn in range(1, turns + 1):
            result = self.play_turn(turn)
            if result is None:
                break
            results.append(result)
        return results

    def leaderboard(self) -> list[tuple[str, int]]:
        return sorted(((hippo.name, hippo.score) for hippo in self.hippos), key=lambda item: (-item[1], item[0]))


def simulate(turns: int = 10, seed: int | None = None) -> Simulator:
    sim = Simulator(rng=Random(seed))
    sim.play(turns)
    return sim

