"""Hungry Hippos simulator.

The game is intentionally lightweight: a fixed number of hippos race for marbles
and the one with the highest haul wins the turn. The module is deterministic
when seeded so tests and demos are repeatable.
"""

from __future__ import annotations

import argparse
import random
from dataclasses import dataclass, field
from typing import Iterable

from toybox.settings import Settings, load

DEFAULT_HIPPOS = 4
DEFAULT_TURNS = 10
DEFAULT_MARBLES = 25
DEFAULT_BITE_RANGE = (0, 3)


@dataclass(frozen=True, slots=True)
class Hippo:
    name: str
    total: int = 0


@dataclass(frozen=True, slots=True)
class TurnResult:
    turn: int
    bites: tuple[int, ...]
    winner: int | None


@dataclass(slots=True)
class Simulator:
    hippos: list[Hippo] = field(default_factory=list)
    marbles: int = DEFAULT_MARBLES
    bite_range: tuple[int, int] = DEFAULT_BITE_RANGE
    rng: random.Random = field(default_factory=random.Random)

    def __post_init__(self) -> None:
        if not self.hippos:
            self.hippos = [Hippo(f"Hippo {i + 1}") for i in range(DEFAULT_HIPPOS)]

    def play_turn(self, turn: int) -> TurnResult:
        bites = [min(self.marbles, self.rng.randint(*self.bite_range)) for _ in self.hippos]
        winner = max(range(len(bites)), key=bites.__getitem__) if any(bites) else None
        if winner is not None:
            self.hippos[winner] = Hippo(self.hippos[winner].name, self.hippos[winner].total + bites[winner])
        return TurnResult(turn=turn, bites=tuple(bites), winner=winner)

    def play(self, turns: int = DEFAULT_TURNS) -> list[TurnResult]:
        return [self.play_turn(turn) for turn in range(1, turns + 1)]

    def leaderboard(self) -> list[Hippo]:
        return sorted(self.hippos, key=lambda hippo: (-hippo.total, hippo.name))


def simulate(turns: int = DEFAULT_TURNS, seed: int | None = None, marbles: int = DEFAULT_MARBLES) -> tuple[Simulator, list[TurnResult]]:
    sim = Simulator(marbles=marbles, rng=random.Random(seed))
    return sim, sim.play(turns)


def format_turn(result: TurnResult, hippos: Iterable[Hippo]) -> str:
    names = [hippo.name for hippo in hippos]
    bites = ", ".join(f"{name}:{bite}" for name, bite in zip(names, result.bites, strict=True))
    if result.winner is None:
        return f"Turn {result.turn}: {bites} | no winner"
    return f"Turn {result.turn}: {bites} | winner={names[result.winner]}"


def format_leaderboard(hippos: Iterable[Hippo]) -> str:
    ordered = list(hippos)
    lines = ["Leaderboard:"]
    for place, hippo in enumerate(ordered, start=1):
        lines.append(f"{place}. {hippo.name} — {hippo.total}")
    return "\n".join(lines)


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="toybox.hippos", description=__doc__)
    parser.add_argument("--turns", type=int, default=DEFAULT_TURNS)
    parser.add_argument("--seed", type=int, default=None)
    parser.add_argument("--marbles", type=int, default=DEFAULT_MARBLES)
    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    settings: Settings = load()
    sim, results = simulate(turns=args.turns, seed=args.seed, marbles=min(args.marbles, settings.width))
    for result in results:
        print(format_turn(result, sim.hippos))
    print(format_leaderboard(sim.leaderboard()))
    return 0


if __name__ == "__main__":  # pragma: no cover
    raise SystemExit(main())
